"""Describe how a callable can be called."""
import inspect


def describe(func):
    spec = inspect.getargspec(func)
    return {
        "args": spec.args,
        "defaults": spec.defaults,
        "varargs": spec.varargs,
        "accepts_kwargs": spec.keywords is not None,
    }

