"""Version comparison for release tags like 1.10 or 2.0rc1."""
from distutils.version import LooseVersion


def parse(text):
    return LooseVersion(text)


def newest(versions):
    return max(versions, key=LooseVersion)


def at_least(version, minimum):
    return LooseVersion(version) >= LooseVersion(minimum)

