import re
import xml.etree.ElementTree as ET


def load(text):
    return ET.fromstring(text)


def items(text):
    root = load(text)
    return [(child.get("id"), child.text) for child in root.getchildren()]


def numbers(text):
    return [int(n) for n in re.findall("\d+", text)]


def read_all(path):
    return open(path).read()

